package S1 {
  port def Door { provides attribute ajar: bool; provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.ajar(n % 2 == 1); send tx.count(n); } schedule { on every 10ms tick(); } }
  component def Reader { reversed port door: Door; attribute seen: bool = false; attribute total: int = 0; operation read() { seen = door.ajar; total = total + door.count; } schedule { on every 10ms read(); } }
  component s: Sensor;
  component r: Reader;
  connect (s.tx, r.door);
}

package S2 {
  port def Door { provides attribute ajar: bool; provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.ajar(n % 2 == 1); send tx.count(n); } schedule { on every 10ms tick(); } }
  component def Reader { reversed port door: Door; attribute seen: bool = false; attribute got: int = 0; operation take(v: int) { got = v; } operation look(v: bool) { seen = door.ajar; } schedule { on receive door.count(v) take(v); on receive door.ajar(v) look(v); } }
  component s: Sensor;
  component r: Reader;
  connect (s.tx, r.door);
}

package S3 {
  port def Door { provides attribute ajar: bool; provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.ajar(n % 2 == 1); send tx.count(n); } schedule { on every 10ms tick(); } }
  component def Reader { reversed port door: Door; attribute k: int = 0; operation m() { initial A; state A { on receive door.count(v) when (door.ajar) to B { k = v; } after 5ms to B { } } state B { on receive door.ajar(v) to A { } } } schedule { on start m(); } }
  component s: Sensor;
  component r: Reader;
  connect (s.tx, r.door);
}

package S4 {
  port def Door { provides attribute ajar: bool; provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.ajar(n % 2 == 1); send tx.count(n); } schedule { on every 10ms tick(); } }
  component def Reader { reversed port door: Door; attribute x: bool = door.ajar; const attribute y: int = door.count; operation read(v: int) { var z: bool = door.ajar; } schedule { on receive door.count(v) read(v); on receive door.ajar(v) read(1); } }
  component s: Sensor;
  component r: Reader;
  connect (s.tx, r.door);
}

package S5 {
  port def Door { provides attribute ajar: bool; provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.ajar(n % 2 == 1); send tx.count(n); } schedule { on every 10ms tick(); } }
  component def Leaf { reversed port p: Door; attribute k: int = 0; operation take(v: int) { k = v; } operation look(v: bool) { } schedule { on receive p.count(v) take(v); on receive p.ajar(v) look(v); } }
  component def Box { reversed port p: Door; component leaf: Leaf; attribute a: bool = false; attribute b: int = 0; connect (p, leaf.p); operation r() { a = p.ajar; b = leaf.p.count; } schedule { on every 10ms r(); } }
  component s: Sensor;
  component b: Box;
  connect (s.tx, b.p);
}

package S6 {
  port def Mixed { provides attribute level: int; provides event ping(n: int); }
  component def C { port tx: Mixed; attribute k: int = 0; operation t() { send tx.level(1); publish tx.ping(2); k = tx.level; k = tx.ping; } schedule { on every 1ms t(); } }
  component c: C;
}

package S7 {
  datatype Pos { ajar: bool; count: int; }
  port def Door { provides attribute ajar: bool; provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.ajar(true); send tx.count(n); } schedule { on every 10ms tick(); } }
  component def Reader { reversed port door: Door; attribute total: int = 0; attribute seen: bool = false;
    operation f(door: Pos) returns int { return door.count; }
    operation take(v: int) { var p: Pos = record Pos { ajar = true; count = v; }; total = total + f(p); }
    operation look(v: bool) { seen = v; }
    schedule { on receive door.count(v) take(v); on receive door.ajar(v) look(v); } }
  component s: Sensor;
  component r: Reader;
  connect (s.tx, r.door);
}

package S8 {
  port def Door { provides attribute ajar: bool; provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.ajar(n % 2 == 1); send tx.count(n); } schedule { on every 10ms tick(); } }
  component def Reader { reversed port door: Door; attribute k: int = 0; operation a(v: int) { k = v; } operation b(v: int) { k = v + 1; } schedule { on receive door.count(v) a(v); on receive door.count(v) b(v); } }
  component s: Sensor;
  component r: Reader;
  connect (s.tx, r.door);
}

package S9 {
  import Swaml::Qos;
  qos def Tight: Policy { delivery = Delivery.atMostOnce; ordering = Ordering.fifo; capacity = 1; overflow = Overflow.dropOldest; requestTimeout = 5ms; }
  qos def Sure: Policy { delivery = Delivery.atLeastOnce; ordering = Ordering.fifo; capacity = 4; overflow = Overflow.dropOldest; requestTimeout = 1s; }
  port def Api { provides operation get() returns int; provides idempotent operation peek() returns int; }
  component def Server { port api: Api; operation get() returns int { return 1; } operation peek() returns int { return 2; } schedule { on call api.get() get(); on call api.peek() peek(); } }
  component def Client { reversed port api: Api; attribute k: int = 0; operation t() { k = api.peek(); } schedule { on start t(); } }
  component sv: Server;
  component cl: Client;
  connect: Sure (cl.api, sv.api);
}

package S10 {
  import Swaml::Qos;
  qos def Tight: Policy { delivery = Delivery.atMostOnce; ordering = Ordering.fifo; capacity = 1; overflow = Overflow.dropOldest; requestTimeout = 5ms; }
  qos def Sure: Policy { delivery = Delivery.atLeastOnce; ordering = Ordering.fifo; capacity = 4; overflow = Overflow.dropOldest; requestTimeout = 1s; }
  port def Bus { provides event frame(n: int); provides attribute level: int; requires operation ask() returns int; }
  component def Bcm { port bus: Bus; attribute n: int = 0; attribute answer: int = 0; operation t() { publish bus.frame(1); publish bus.frame(2); publish bus.frame(3); send bus.level(1); send bus.level(2); answer = try(bus.ask(), -1); } schedule { on start t(); } }
  component def Dcu { reversed port bus: Bus; attribute frames: int = 0; attribute last: int = 0; attribute lv: int = 0;
    operation m() { initial A; state A { on receive bus.frame(n) to B { frames = frames + 1; last = n; } on receive bus.level(v) to A { lv = v; } } state B { after 2ms to A { } } }
    operation ask() returns int { wait 10ms; return 7; }
    schedule { on start m(); on call bus.ask() ask(); } }
  component bcm: Bcm;
  component dcu: Dcu;
  connect link: Tight (bcm.bus, dcu.bus);
}

package S11 {
  import Swaml::Qos;
  qos def Tight: Policy { delivery = Delivery.atMostOnce; ordering = Ordering.fifo; capacity = 1; overflow = Overflow.dropOldest; requestTimeout = 5ms; }
  qos def Sure: Policy { delivery = Delivery.atLeastOnce; ordering = Ordering.fifo; capacity = 4; overflow = Overflow.dropOldest; requestTimeout = 1s; }
  port def Bus { provides event frame(n: int); }
  component def Bcm { port bus: Bus; operation t() { publish bus.frame(1); publish bus.frame(2); publish bus.frame(3); } schedule { on start t(); } }
  component def Dcu { reversed port bus: Bus; attribute frames: int = 0; operation m() { initial A; state A { on receive bus.frame(n) to B { frames = frames + 1; } } state B { after 1ms to A { } } } schedule { on start m(); } }
  component def Base { component bcm: Bcm; component dcu: Dcu; connect link: Tight (bcm.bus, dcu.bus); }
  component def Wide specializes Base { redefines connect link: Sure (bcm.bus, dcu.bus); }
  component a: Base;
  component b: Wide;
  component c: Base { redefines connect link: Sure (bcm.bus, dcu.bus); }
}

package S12 {
  import Swaml::Qos;
  qos def Aged: Policy { delivery = Delivery.bestEffort; ordering = Ordering.fifo; capacity = 4; overflow = Overflow.dropOldest; requestTimeout = 1s; maxAge = 2ms; }
  port def Door { provides attribute count: int; }
  component def Sensor { port tx: Door; attribute n: int = 0; operation tick() { n = n + 1; send tx.count(n); send tx.count(n + 100); } schedule { on every 10ms tick(); } }
  component def Reader { reversed port door: Door; attribute got: int = 0; attribute seen: int = 0; operation take(v: int) { got = v; seen = seen + 1; } schedule { on receive door.count(v) take(v); } }
  component s: Sensor;
  component r: Reader;
  component s2: Sensor;
  component r2: Reader;
  connect (s.tx, r.door);
  connect: Aged (s2.tx, r2.door);
}

package S13 {
  port def Door { provides attribute ajar: bool; }
  component def Sensor { port tx: Door; operation tick() { send tx.ajar(true); } schedule { on every 10ms tick(); } }
  component def Probe { reversed port watch: Door; }
  component sensor: Sensor;
  component probe: Probe;
  connect (sensor.tx, probe.watch);
  associate probe to 'Reads';
  test 'Reads' of sensor { on receive probe.watch.ajar(v) { assert v; } or after 20ms { fail "no value"; } assert probe.watch.ajar; }
}

package S14 {
  import Swaml::Qos;
  qos def Tight: Policy { delivery = Delivery.atMostOnce; ordering = Ordering.fifo; capacity = 1; overflow = Overflow.dropOldest; requestTimeout = 5ms; }
  qos def Sure: Policy { delivery = Delivery.atLeastOnce; ordering = Ordering.fifo; capacity = 4; overflow = Overflow.dropOldest; requestTimeout = 1s; }
  port def Api { provides operation get() returns int; provides event e(n: int); }
  component def Server { port api: Api; operation get() returns int { return 1; } operation t() { publish api.e(1); } schedule { on call api.get() get(); on start t(); } }
  component def Client { reversed port api: Api; attribute k: int = 0; operation take(n: int) { var x: int = api.get(); k = n + x; } schedule { on receive api.e(n) take(n); } }
  component sv: Server;
  component cl: Client;
  connect pk: Sure (cl.api, sv.api);
}

package S15 {
  import Swaml::Qos;
  qos def Tight: Policy { delivery = Delivery.atMostOnce; ordering = Ordering.fifo; capacity = 1; overflow = Overflow.dropOldest; requestTimeout = 5ms; }
  qos def Sure: Policy { delivery = Delivery.atLeastOnce; ordering = Ordering.fifo; capacity = 4; overflow = Overflow.dropOldest; requestTimeout = 1s; }
  port def Bus { provides event frame(n: int); }
  component def Dcu { reversed port bus: Bus; attribute frames: int = 0; attribute last: int = 0; operation m() { initial A; state A { on receive bus.frame(n) to B { frames = frames + 1; last = n; } } state B { after 2ms to A { } } } schedule { on start m(); } }
  component def Bcm { port bus: Bus; }
  component dcu: Dcu;
  component bcm: Bcm;
  connect: Tight (bcm.bus, dcu.bus);
  associate bcm to 'Burst';
  test 'Burst' of dcu { publish bcm.bus.frame(1); publish bcm.bus.frame(2); publish bcm.bus.frame(3); wait 10ms; assert dcu.frames == 2 and dcu.last == 3; }
}

package S16 {
  component def M { attribute n: int = 0; attribute done: bool = false; operation bump() { n = n + 1; } operation m() { initial A; state A { after 1ms to A { } on entry { if (n > 3) { done = true; } } } } schedule { on start m(); on every 2ms bump(); } }
  component m: M;
}
